// Lua script executed atomically via Redis Lua EVAL
// Checks seat status and transitions AVAILABLE -> HELD in one round-trip
const holdSeatLua = `
local seatKey = KEYS[1]          -- seats:{eventId}:{seatId}
local userKey = ARGV[1]          -- userId
local ttl = tonumber(ARGV[2])    -- hold TTL in seconds
local holdId = ARGV[3]           -- idempotency holdId

local current = redis.call('HGET', seatKey, 'status')
if current == 'BOOKED' then
  return { 'ERR', 'Seat already booked' }
end
if current == 'HELD' then
  local heldBy = redis.call('HGET', seatKey, 'heldBy')
  if heldBy == userKey then
    -- extend existing hold of same user (idempotent re-hold)
    redis.call('EXPIRE', seatKey, ttl)
    return { 'OK', 'extended' }
  end
  return { 'ERR', 'Seat held by another user' }
end

redis.call('HSET', seatKey, 'status', 'HELD', 'heldBy', userKey, 'holdId', holdId)
redis.call('EXPIRE', seatKey, ttl)
return { 'OK', 'held' }
`;

// Usage in InventoryService
public async Task<SeatHoldResult> HoldSeatAsync(string eventId, string seatId, string userId, int ttlSeconds)
{
    var seatKey = string.Format("seats:{0}:{1}", eventId, seatId);
    var result = await _redis.ExecuteAsync(LuaScript.Prepare(holdSeatLua), seatKey, userId, ttlSeconds, Guid.NewGuid().ToString());
