}

// MassTransit state machine for booking Saga
public class BookingStateMachine : MassTransitStateMachine<BookingSaga>
{
    public State Held     { get; private set; }
    public State Paid     { get; private set; }
    public State Confirmed { get; private set; }
    public State Expired  { get; private set; }

    public Event<SeatHoldRequested> SeatHoldRequested   { get; private set; }
    public Event<PaymentSucceeded> PaymentSucceeded     { get; private set; }
    public Event<PaymentFailed>    PaymentFailed        { get; private set; }
    public Event<HoldExpired>      HoldExpired          { get; private set; }

    public void Configure()
    {
        InstanceState(x => x.CurrentState);

        Event(() => SeatHoldRequested, x => x.CorrelateById(m => m.Message.BookingId));
        Event(() => PaymentSucceeded, x => x.CorrelateById(m => m.Message.BookingId));
        Event(() => PaymentFailed,    x => x.CorrelateById(m => m.Message.BookingId));
        Event(() => HoldExpired,      x => x.CorrelateById(m => m.Message.BookingId));

        Initially(
            When(SeatHoldRequested)
                .Then(context =>
                {
                    context.Saga.HoldId = context.Message.HoldId;
                    context.Saga.Seats = context.Message.Seats;
                    context.Saga.HoldExpiresAt = DateTime.UtcNow.AddMinutes(10);
                })
                .TransitionTo(Held)
                .SendAsync(x => x.Initiate<PaymentRequested>(new PaymentRequestedMessage
                {
                    BookingId = x.Message.BookingId,
                    Amount = x.Message.Amount,
                    PaymentMethod = x.Message.PaymentMethod
                }))
        );

        During(Held,
            When(PaymentSucceeded)
                .TransitionTo(Confirmed)
                .Then(context =>
                {
                    context.Saga.BookingConfirmedAt = DateTime.UtcNow;
                    context.Saga.Status = "Confirmed";
                })
                .Publish(context => new BookingConfirmed
                {
                    BookingId = context.Saga.CorrelationId,
                    Seats = context.Saga.Seats
                })
                .Finalize(),
            When(PaymentFailed)
                .TransitionTo(Expired)
                .Publish(context => new BookingCancelled
                {
                    BookingId = context.Saga.CorrelationId,
                    Reason = "Payment failed"
                })
                .Finalize(),
            When(HoldExpired)
                .TransitionTo(Expired)
                .Publish(context => new BookingCancelled
                {
                    BookingId = context.Saga.CorrelationId,
                    Reason = "Hold expired"
                })
                .Finalize()
        );
    }
}
